// The catalog build (CATALOG_SPEC 6): check catalog/, then produce the generated files. Pure and
// deterministic (no dates): the same catalog and engine give the same bytes, so a test can rebuild in
// memory and compare with the committed files. tools/catalog_build.mjs is the CLI that writes them.

import { createHash } from "node:crypto";
import { validate } from "../../engine/index.js";
import { WORLD_COMMANDS } from "../../engine/validator/index.js";
import { WORLD_COMMANDS_V2 } from "../../engine/validator/semantic.js";
import { MACRO_PARAMS, MACRO_ANCHORS } from "../../engine/validator/macro_params.js";
import { V2_ENUMS, DEFEAT_STYLES_BY_AUDIENCE, OBJECT_BEHAVIORS } from "../../engine/validator/v2_names.js";
import { jsonSchemaV2 } from "../../engine/validator/schema_v2.js";
import { CATEGORIES } from "../../engine/moves.js";
import { LIMITS, LIMITS_V2 } from "../../engine/config.js";
import { educationOf } from "../../catalog/index.js";
import { formatJson } from "./json_format.mjs";
import { checkCatalog, goodThemes } from "./catalog_check.mjs";
import { buildPack, PACK_FILES } from "./context_pack.mjs";

/** Catalog format version: bump when the layout of catalog/ or of the generated files changes. */
export const SCHEMA_VERSION = 1;
export const GENERATED_NOTE = "Built by `npm run catalog:build` from catalog/ and engine/. Do not edit: change catalog/ and rebuild.";
const MD_NOTE = "<!-- generated by npm run catalog:build; do not edit -->\n";

/** The schema of a cast entry's voice, found in the v2 schema (ranges for the vocabulary file). */
function voiceRanges() {
  let found = null;
  const walk = (s) => {
    if (!s || typeof s !== "object" || found) return;
    if (s.properties?.pitch && s.properties?.timbre) found = s.properties;
    else Object.values(s).forEach(walk);
  };
  walk(jsonSchemaV2);
  return { pitch: [found.pitch.minimum, found.pitch.maximum], speed: [found.speed.minimum, found.speed.maximum], timbre: found.timbre.enum };
}

/** The engine-owned vocabularies, exported for tools and AI (CATALOG_SPEC 3.3). */
export function engineVocab(codes) {
  return {
    _generated: GENERATED_NOTE,
    enums: V2_ENUMS,
    moveCategories: CATEGORIES,
    objectBehaviors: OBJECT_BEHAVIORS,
    defeatStylesByAudience: DEFEAT_STYLES_BY_AUDIENCE,
    voice: voiceRanges(),
    worldCommands: Object.fromEntries(Object.entries(WORLD_COMMANDS_V2).map(([n, spec]) => [n, { v1: n in WORLD_COMMANDS, params: spec }])),
    macroParams: MACRO_PARAMS,
    macroAnchors: MACRO_ANCHORS,
    limits: { v1: LIMITS, v2: LIMITS_V2 },
    codes: [...codes].sort(),
  };
}

/** What each example is: its length and the macros and moves it uses. */
function exampleFacts(src) {
  return src.files["examples/index.json"].examples.map((e) => {
    const ex = src.examples[e.path];
    const script = e.kind === "story" ? ex.story : ex;
    const beats = (script.beats || []).concat((script.scenes || []).flatMap((s) => s.beats || []));
    const r = validate(script, src.catalog);
    return {
      ...e,
      seconds: Math.round(r.durationSec ?? 0),
      macros: [...new Set(beats.filter((b) => b.macro).map((b) => b.macro).concat((script.scenes || []).filter((s) => s.macro).map((s) => s.macro)))].sort(),
      moves: [...new Set(beats.filter((b) => b.who && b.who !== "world").map((b) => b.do))].sort(),
    };
  });
}

const hash = (texts) => createHash("sha256").update(texts.join("\u0000")).digest("hex").slice(0, 10);

/**
 * @param {ReturnType<import("./catalog_files.mjs").readCatalogDir>} src
 * @param {{ codes: Set<string> }} opts
 * @returns {{ ok: boolean, issues: object[], files: Record<string, string>, version?: string, sizes?: Record<string, number> }}
 *   files: paths relative to catalog/ → contents
 */
export function buildCatalog(src, { codes }) {
  const issues = checkCatalog(src, { codes });
  if (issues.length) return { ok: false, issues, files: {} };

  const facts = { goodThemes: Object.fromEntries(src.presets.map((p) => [p.id, goodThemes(p, src.catalog)])) };
  const { roles } = src.files["characters/roles.json"];
  const full = {
    catalog: src.catalog,
    presets: src.presets.map(({ file, ...p }) => ({ ...p, goodThemes: facts.goodThemes[p.id] })),
    roles,
    // Descriptions the engine catalog leaves out (it keeps the names only).
    sfx: src.files["effects/sfx.json"],
    appearance: Object.fromEntries(Object.entries(src.files["characters/appearance.json"]).filter(([k]) => k !== "conflicts").map(([k, list]) => [k, Object.fromEntries(list.map((o) => [o.name, o.description]))])),
    voices: src.files["characters/voices.json"].timbres,
    ambience: src.files["world/ambience.json"].beds,
    docs: Object.fromEntries(["world_commands", "macros", "camera", "transitions", "codes", "workbook_activities"].map((d) => [d, src.files[`docs/${d}.json`]])),
    examples: exampleFacts(src),
    pack: src.files["examples/index.json"].pack,
    // Workbooks (WORKBOOK_SPEC 8): shapes, shape pictures, colours and print approvals.
    education: educationOf(src.files),
  };
  const vocab = formatJson(engineVocab(codes));
  const fullText = formatJson({ _generated: GENERATED_NOTE, ...full });
  const draft = buildPack({ ...src, facts }, "0");
  const version = `${SCHEMA_VERSION}-${hash([vocab, fullText, ...Object.entries(draft).filter(([f]) => f !== "00_start_here.md" && f !== "project_instructions.md").map(([, t]) => t)])}`;
  const pack = buildPack({ ...src, facts }, version);

  const files = { "generated/engine_vocab.json": vocab, "generated/catalog.json": fullText };
  for (const [f, text] of Object.entries(pack)) files[`generated/context/${f}`] = f.endsWith(".md") && f !== "project_instructions.md" ? MD_NOTE + text : text;
  const sizes = Object.fromEntries(Object.entries(files).map(([f, t]) => [f, Buffer.byteLength(t)]));
  const c = src.catalog;
  const manifest = {
    _generated: GENERATED_NOTE,
    schemaVersion: SCHEMA_VERSION,
    version,
    counts: {
      moves: c.moves.length, poses: Object.keys(c.poses).length, fx: Object.keys(c.fxPresets).length, sfx: c.sfxKeys.length,
      themes: c.themeNames.length, objects: Object.keys(c.objects).length, props: Object.keys(c.props).length, faces: c.faceNames.length,
      bodies: c.bodyNames.length, activities: c.activityNames.length, moods: Object.keys(c.musicMoods).length, macros: Object.keys(MACRO_PARAMS).length,
      worldCommands: Object.keys(WORLD_COMMANDS_V2).length, codes: codes.size, presets: src.presets.length, examples: full.examples.length,
      shapes: Object.keys(full.education.shapes).length, shapePictures: Object.keys(full.education.pictures).length,
      dotPictures: Object.keys(full.education.dotPictures).length, wordTopics: Object.keys(full.education.words.topics).length,
      words: Object.values(full.education.words.topics).reduce((n, t) => n + Object.keys(t.words).length, 0),
      mathTemplates: Object.keys(full.education.math.templates).length, questionSets: Object.keys(full.education.questions.sets).length,
      questions: Object.values(full.education.questions.sets).reduce((n, q) => n + q.questions.length, 0), passages: Object.keys(full.education.passages.passages).length,
      skills: Object.keys(full.education.skills.skills).length, workbookActivities: Object.keys(full.docs.workbook_activities).length,
    },
    authored: src.authored,
    pack: Object.fromEntries(Object.entries(PACK_FILES).map(([f, m]) => [f, { tier: m.tier, budget: m.budget, bytes: sizes[`generated/context/${f}`] }])),
    generated: Object.fromEntries(Object.entries(sizes).map(([f, b]) => [f, b])),
  };
  files["manifest.json"] = formatJson(manifest);
  return { ok: true, issues: [], files, version, sizes };
}
